const body = $input.first().json.body || $input.first().json;
const action = (body.action || '').toLowerCase();
const actor = (body.actor || '').trim();
const reason = (body.reason || '').trim();

if (!['freeze', 'unfreeze'].includes(action)) {
  throw new Error('action must be "freeze" or "unfreeze"');
}
if (!actor) {
  throw new Error('actor is required so the emergency action is auditable (see ADR-004)');
}

return [{
  json: {
    action,
    actor,
    reason: reason || (action === 'freeze' ? 'Manual emergency stop' : 'Manual restore'),
    is_frozen: action === 'freeze',
    timestamp: new Date().toISOString()
  }
}];

const v = $('Validate Request').first().json;
return [{
  json: {
    status: v.action === 'freeze' ? 'FROZEN' : 'UNFROZEN',
    is_frozen: v.is_frozen,
    actor: v.actor,
    reason: v.reason,
    timestamp: v.timestamp,
    message: v.action === 'freeze'
      ? '🚨 Emergency Stop Activated - All Payment Pipelines Halted'
      : '✅ System restored - payment pipeline resumed'
  }
}];
